      type="number"
      disabled={disabled}
      min={input.min_value}
      max={input.max_value}
      value={value ?? ''}
      onChange={(event) => {
        const rawValue = event.target.value;
        if (rawValue === '') {
          onChange(null);
          return;
        }
        onChange(Number(rawValue));
      }}
    />
  );
};
