[metadata] {"type": "create", "filePath": "/workspace/repo/mlflow/server/js/src/experiment-tracking/components/label-schemas/widgets/LabelSchemaInputCategorical.tsx", "content": "import {
  DialogCombobox,
  DialogComboboxContent,
  DialogComboboxOptionList,
  DialogComboboxOptionListCheckboxItem,
  DialogComboboxOptionListSelectItem,
  DialogComboboxTrigger,
} from '@databricks/design-system';

export interface LabelSchemaInputCategoricalProps {
  input: { options: string[]; multi_select?: boolean };
  value: string | string[] | null | undefined;
  onChange: (value: string | string[]) => void;
  componentId: string;
  label: string;
  disabled?: boolean;
}

/**
 * Categorical label-schema input. Renders a combobox (role="combobox")
 * accessible by the `label` prop. When `multi_select` is absent or false the
 * control is single-select; when true it is multi-select.
 */
export const LabelSchemaInputCategorical = ({
  input,
  value,
  onChange,
  componentId,
  label,
  disabled,
}: LabelSchemaInputCategoricalProps) => {
  const multiSelect = Boolean(input.multi_select);

  if (multiSelect) {
    const selectedValues = Array.isArray(value) ? value : [];

    const toggleOption = (option: string) => {
      const nextValues = selectedValues.includes(option)
        ? selectedValues.filter((item) => item !== option)
        : [...selectedValues, option];
      onChange(nextValues);
    };

    return (
      <DialogCombobox componentId={componentId} label={label} value={selectedValues} multiSelect>
        <DialogComboboxTrigger disabled={disabled} allowClear={false} />
        <DialogComboboxContent>
          <DialogComboboxOptionList>
            {input.options.map((option) => (
              <DialogComboboxOptionListCheckboxItem
                key={option}
                value={option}
                checked={selectedValues.includes(option)}
                onChange={() => toggleOption(option)}
              >
                {option}
              </DialogComboboxOptionListCheckboxItem>
            ))}
          </DialogComboboxOptionList>
        </DialogComboboxContent>
      </DialogCombobox>
    );
  }

  const selectedValue = typeof value === 'string' ? value : undefined;

  return (
    <DialogCombobox componentId={componentId} label={label} value={selectedValue ? [selectedValue] : []}>
      <DialogComboboxTrigger disabled={disabled} allowClear={false} />
      <DialogComboboxContent>
        <DialogComboboxOptionList>
          {input.options.map((option) => (
            <DialogComboboxOptionListSelectItem
              key={option}
              value={option}
              checked={selectedValue === option}
              onChange={() => onChange(option)}
            >
              {option}
            </DialogComboboxOptionListSelectItem>
          ))}
        </DialogComboboxOptionList>
      </DialogComboboxContent>
    </DialogCombobox>
  );
};
