import type { LabelSchemaInput } from '../types';
import { LabelSchemaInputPassFail } from './LabelSchemaInputPassFail';
import { LabelSchemaInputNumeric } from './LabelSchemaInputNumeric';
import { LabelSchemaInputCategorical } from './LabelSchemaInputCategorical';

export interface LabelSchemaInputRendererProps {
  input: LabelSchemaInput;
  value: any;
  onChange: (value: any) => void;
  componentId: string;
  label?: string;
  disabled?: boolean;
  instruction?: string;
}

/**
 * Dispatcher component that renders the matching widget based on which variant
 * is set on the `input` object. When no recognized variant is set, renders an
 * "Invalid label schema" error message.
 */
export const LabelSchemaInputRenderer = ({
  input,
  value,
  onChange,
  componentId,
  label,
  disabled,
}: LabelSchemaInputRendererProps) => {
  if (input.pass_fail) {
    return (
      <LabelSchemaInputPassFail
        input={input.pass_fail}
        value={value}
        onChange={onChange}
        componentId={componentId}
        disabled={disabled}
      />
    );
  }

  if (input.numeric) {
    return (
      <LabelSchemaInputNumeric
        input={input.numeric}
        value={value}
        onChange={onChange}
        componentId={componentId}
        disabled={disabled}
      />
    );
  }

  if (input.categorical) {
    return (
      <LabelSchemaInputCategorical
        input={input.categorical}
        value={value}
        onChange={onChange}
        componentId={componentId}
        label={label ?? ''}
        disabled={disabled}
      />
    );
  }

  if (input.text) {
    return (
      <Input
        componentId={componentId}
        value={value ?? ''}
        disabled={disabled}
        maxLength={input.text.max_length}
        onChange={(event) => onChange(event.target.value)}
      />
    );
  }

  return (
    <Alert
      componentId={`${componentId}.error`}
      type="error"
      closable={false}
      message={
        <FormattedMessage
          defaultMessage="Invalid label schema"
          description="Error message shown when a label schema input has no recognized variant"
        />
      }
    />
  );
};
